script:
import Reveal from "https://cdn.jsdelivr.net/npm/reveal.js@5.2.1/dist/reveal.esm.js";
import Notes from "https://cdn.jsdelivr.net/npm/reveal.js@5.2.1/plugin/notes/notes.esm.js";

const deck = new Reveal({
  hash: true,
  controls: true,
  progress: true,
  center: true,
  transition: "slide",
  backgroundTransition: "fade",
  width: 1280,
  height: 720,
  margin: 0.055,
  plugins: [Notes],
});

deck.initialize();

css:
:root { color-scheme: dark; }
body { margin: 0; background: #070707; }

.club-deck {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.club-deck .slides { text-align: left; }

.club-deck h1,
.club-deck h2 {
  font-family: Fraunces, Georgia, serif;
  font-weight: 800;
  letter-spacing: -0.05em;
  text-transform: none;
}

.club-deck h1 {
  max-width: 820px;
  font-size: clamp(3.2rem, 6.3vw, 6.2rem);
  line-height: 0.92;
}

.club-deck h2 {
  max-width: 1020px;
  font-size: clamp(2.8rem, 5.4vw, 5.25rem);
  line-height: 0.95;
}

.club-deck p,
.club-deck li {
  max-width: 900px;
  font-size: 1.85rem;
  line-height: 1.18;
}

.club-deck ul { margin-left: 1.2em; }
.club-deck li + li { margin-top: 0.5em; }

.club-deck .eyebrow {
  margin: 0 0 1.1rem;
  color: #ffc857;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.club-deck .subtitle { color: #f4eadc; font-size: 1.9rem; }
.club-deck .small { font-size: 1.05rem; }
.club-deck .muted { color: #b7aea2; }

.club-deck .big {
  font-size: clamp(2rem, 3.7vw, 3.8rem);
  line-height: 1.05;
}

.club-deck .punch { color: #ffc857; font-weight: 800; }

.club-deck .reveal-line {
  color: #fff;
  font-family: Fraunces, Georgia, serif;
  font-size: clamp(2.9rem, 5.7vw, 5.25rem);
  font-weight: 900;
  letter-spacing: -0.05em;
  line-height: 0.98;
}

.club-deck .end-card {
  display: inline-block;
  margin-top: 2rem;
  padding: 0.25em 0.45em;
  border: 0.08em solid #ffc857;
  color: #ffc857;
  font-family: Fraunces, Georgia, serif;
  font-size: 5rem;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.club-deck .stat {
  margin: 1.2rem 0 0;
  color: #ffc857;
  font-family: Fraunces, Georgia, serif;
  font-size: clamp(4rem, 7vw, 6.6rem);
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 0.85;
}

.club-deck .stat span {
  color: #f4eadc;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0;
}

.club-deck .grid-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.8rem;
  margin: 1.5rem 0 2rem;
}

.club-deck .grid-3 p {
  min-height: 115px;
  margin: 0;
  padding: 0.8rem;
  border: 1px solid rgba(255, 200, 87, 0.34);
  border-radius: 1rem;
  background: rgba(255, 255, 255, 0.05);
  font-family: Fraunces, Georgia, serif;
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.club-deck .compact-grid { max-width: 760px; }

.club-deck .visual-split,
.club-deck .meme-slide {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
  gap: 2.4rem;
  align-items: center;
}

.club-deck .wide-media {
  grid-template-columns: minmax(0, 0.95fr) minmax(460px, 1.05fr);
}

.club-deck .meme-slide {
  grid-template-columns: minmax(460px, 0.92fr) minmax(0, 1.08fr);
}

.club-deck .meme-slide-right {
  grid-template-columns: minmax(0, 1.05fr) minmax(440px, 0.95fr);
}

.club-deck .media {
  margin: 0;
  align-self: center;
}

.club-deck .media a {
  display: block;
  border: 0;
  color: inherit;
  text-decoration: none;
}

.club-deck .media img {
  display: block;
  width: 100%;
  max-height: 520px;
  object-fit: cover;
  border-radius: 1.15rem;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.38);
}

.club-deck .portrait img { aspect-ratio: 4 / 5; }
.club-deck .portrait.tall img { max-height: 560px; }
.club-deck .landscape img { aspect-ratio: 16 / 10; }

.club-deck .meme-card img {
  max-height: 560px;
  object-fit: contain;
  border: 2px solid rgba(255, 200, 87, 0.55);
  background: rgba(255, 255, 255, 0.06);
}

.club-deck .logo-card {
  padding: 2rem;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 1.2rem;
  background: rgba(255, 255, 255, 0.94);
}

.club-deck .logo-card img {
  max-height: 220px;
  object-fit: contain;
  border-radius: 0;
  box-shadow: none;
}

.club-deck figcaption,
.club-deck .media-credit,
.club-deck .credit-row {
  margin: 0.55rem 0 0;
  color: #c9c4bc;
  font-size: 1rem;
  line-height: 1.2;
}

.club-deck figcaption a,
.club-deck .media-credit a { color: inherit; }

.club-deck .collision {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr) 220px;
  gap: 1.5rem;
  align-items: center;
}

.club-deck .collision-copy { text-align: center; }
.club-deck .collision-copy h2 { margin-left: auto; margin-right: auto; }
.club-deck .collision-copy p { margin-left: auto; margin-right: auto; }
.club-deck .mini img { max-height: 390px; }
.club-deck .credit-row { text-align: center; }

.club-deck .video-shell {
  overflow: hidden;
  width: 820px;
  max-width: 100%;
  aspect-ratio: 16 / 9;
  border: 2px solid rgba(255, 200, 87, 0.5);
  border-radius: 1.4rem;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
}

.club-deck iframe { width: 100%; height: 100%; border: 0; }
.club-deck .logo-card figcaption { color: #444; }
.club-deck .uncropped img { aspect-ratio: 16 / 9; object-fit: contain; }
.club-deck .teaser-slide h2 { font-size: 3rem; margin-bottom: 1rem; }
.club-deck .teaser-slide .video-shell { margin: 0 auto; }
.club-deck .teaser-slide .media-credit { text-align: center; }
.club-deck .meme-focus { text-align: center; }
.club-deck .meme-focus h2 { font-size: 3rem; max-width: none; margin-bottom: 1rem; }
.club-deck .meme-focus .eyebrow { display: none; }
.club-deck .meme-focus figure { width: 760px; max-width: 100%; margin: 0 auto; }
.club-deck .meme-focus img { max-height: 490px; width: 100%; object-fit: contain; }

.club-deck .sources li { font-size: 1.35rem; }

.deck-help {
  position: fixed;
  left: 1rem;
  bottom: 0.75rem;
  z-index: 20;
  display: flex;
  gap: 0.6rem;
  color: rgba(255, 255, 255, 0.62);
  font: 700 0.72rem/1 Inter, ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  pointer-events: none;
}

.deck-help span {
  padding: 0.45rem 0.6rem;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(8px);
}

@media (max-width: 760px) {
  .club-deck .visual-split,
  .club-deck .wide-media,
  .club-deck .grid-3,
  .club-deck .collision,
  .club-deck .meme-slide,
  .club-deck .meme-slide-right {
    grid-template-columns: 1fr;
  }

  .club-deck .media img { max-height: 300px; }
  .club-deck .mini { display: none; }
  .deck-help { display: none; }
}
